enum ListingIssue { missingTitle, missingDescription, invalidPrice, invalidCurrency, negativeStock }
class ListingDraft { const ListingDraft({required this.title,required this.description,required this.price,required this.currency,required this.stock}); final String title,description,currency; final num price; final int stock; }
class ListingQualityResult { const ListingQualityResult(this.issues,this.score); final List<ListingIssue> issues; final int score; bool get isReady=>issues.isEmpty; }
class ListingQualityAssessor { const ListingQualityAssessor(); ListingQualityResult assess(ListingDraft d){final e=<ListingIssue>[];if(d.title.trim().length<3)e.add(ListingIssue.missingTitle);if(d.description.trim().length<10)e.add(ListingIssue.missingDescription);if(!d.price.isFinite||d.price<=0)e.add(ListingIssue.invalidPrice);if(!RegExp(r'^[A-Z]{3}$').hasMatch(d.currency.trim().toUpperCase()))e.add(ListingIssue.invalidCurrency);if(d.stock<0)e.add(ListingIssue.negativeStock);return ListingQualityResult(List.unmodifiable(e),((5-e.length)*20).clamp(0,100));}}
